const tasks = [
  { name: 'API', days: 5, deps: [] },
  { name: 'UI', days: 3, deps: ['API'] },
  { name: 'Test', days: 3, deps: ['UI'] }
];
const finish = {};
for (const t of tasks) {
  const depEnd = t.deps.map(d => finish[d] || 0);
  finish[t.name] = t.days + Math.max(0, ...depEnd);
}
console.log(tasks.map(t => t.name + ':' + finish[t.name]).join(','));

